    "closedItems": {
      "description": "Open items on Epics that this Vision closes, one entry per item: { artifact: epic | epic-enabler, unit: <the Epic's id, e.g. E-2>, item: <the openItems id>, resolution: <one line> }. The epic-vision-alignment run for that Epic flips each one to `resolved` there; epic-transition accepts only a no-change refusal on that Epic while one is still `open` there.",
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "artifact",
          "unit",
          "item",
          "resolution"
        ],
        "properties": {
          "artifact": {
            "description": "Kind of the artifact holding the item.",
            "enum": [
              "epic",
              "epic-enabler"
            ]
          },
          "unit": {
            "description": "The `id` of that Epic or Enabler Epic.",
            "type": "string",
            "minLength": 1
          },
          "item": {
            "description": "The `id` of the closed `openItems` entry.",
            "type": "string",
            "minLength": 1
          },
          "resolution": {
            "description": "One line: how the Vision resolves it.",
            "type": "string",
            "minLength": 1
          }
        }
      }
    },
    "cost": {
      "description": "Token-cost accounting block (see the cost definition).",
      "$ref": "#/$defs/cost"
    },
    "github": {
      "description": "GitHub Projects sync envelope, filled by portfolio/_sync (null when authoring).",
      "$ref": "#/$defs/githubSync"
    },
    "sources": {
      "description": "Derivation provenance (narrowed subtype of the base contract's sources): refs to the upstream artifact(s) this architecture-vision was built from. Allowed source kinds: strategic-themes, portfolio-vision.",
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "string",
        "pattern": "(^|/)([a-z0-9-]+\\.)?(strategic-themes|portfolio-vision)\\.md$"
      }
    },
    "stepOutcomes": {
