  "additionalProperties": true,
  "x-artifact": {
    "id": "adr",
    "kind": "adr",
    "template": "templates/layers/program/actors/system-architect/artifacts/adr.artifact-template.md",
    "pathPatterns": [
      "portfolio/art/*/program-backlog/*/*.adr.md"
    ],
    "renderOnly": false
  },
  "required": [
    "status"
  ],
  "properties": {
    "status": {
      "description": "proposed | accepted | rejected | superseded",
      "type": "string",
      "minLength": 1
    },
    "title": {
      "description": "Human-readable title of the artifact.",
      "type": "string",
      "minLength": 1
    },
    "workItemRelations": {
      "description": "Typed work-item relations (dependsOn / enables / relatedTo / supersedes).",
      "$ref": "#/$defs/workItemRelations"
    },
    "wsjf": {
      "description": "Weighted Shortest Job First scoring block.",
      "$ref": "#/$defs/wsjf"
    },
    "risk": {
      "description": "Risk level \u2014 the consequence of being wrong: low | medium | critical.",
      "enum": [
        "low",
        "medium",
        "critical"
      ]
    },
    "complexity": {
      "description": "Complexity \u2014 cognitive/structural difficulty: simple | involved | complex.",
      "enum": [
        "simple",
        "involved",
        "complex"
      ]
    },
    "created": {
      "description": "Authoring date (YYYY-MM-DD).",
      "type": "string",
      "minLength": 1
    },
    "openItems": {
      "description": "Clarification + challenge ledger (a blocking open entry halts the relevant gate).",
      "$ref": "#/$defs/openItems"
    },
    "cost": {
      "description": "Token-cost accounting block (see the cost definition).",
      "$ref": "#/$defs/cost"
    },
    "github": {
      "description": "GitHub Projects sync envelope, filled by portfolio/_sync (null when authoring).",
      "$ref": "#/$defs/githubSync"
    },
    "sources": {
      "description": "Derivation provenance (narrowed subtype of the base contract's sources): refs to the upstream artifact(s) this adr was built from. Allowed source kinds: feature, feature-enabler.",
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "string",
        "pattern": "(^|/)([a-z0-9-]+\\.)?(feature|feature-enabler)\\.md$"
      }
    },
    "stepOutcomes": {
      "description": "Step outcome record \u2014 one entry per step that committed this artifact (see the stepOutcomes definition).",
      "$ref": "#/$defs/stepOutcomes"
    }
  },
  "$defs": {
    "cost": {
      "description": "Token-cost accounting block.",
      "type": "object",
      "additionalProperties": true,
      "required": [
        "tokensIn",
        "tokensOut",
        "tokensCached",
        "tokensSelf",
        "tokensRolled",
        "dispatches",
        "source",
        "committed"
      ],
      "properties": {
        "tokensIn": {
          "description": "NET-NEW prompt tokens = sum(inputTokens - cachedTokens) of this item's dispatches.",
          "type": "number"
        },
        "tokensOut": {
          "description": "Sum of outputTokens of those dispatches.",
          "type": "number"
        },
        "tokensCached": {
          "description": "Sum of cachedTokens (re-sent context); excluded from tokensSelf, kept for billed-cost reconstruction.",
          "type": "number"
        },
        "tokensSelf": {
          "description": "tokensIn + tokensOut - the item's own net cost.",
          "type": "number"
        },
        "tokensRolled": {
          "description": "tokensSelf plus the rolled cost of child items - the item's end-to-end cost.",
          "type": "number"
        },
        "dispatches": {
          "description": "Number of subagent dispatches counted into tokensSelf (not llm_request turns).",
          "type": "number"
        },
        "source": {
          "description": "Provenance of the cost figures: measured, estimated, or mixed.",
          "enum": [
            "measured",
            "estimated",
            "mixed"
          ]
        },
        "committed": {
          "description": "YYYY-MM-DD the one-time cost snapshot was written; immutable after (null until committed).",
          "type": [
            "string",
            "null"
          ]
        }
      }
