      "type": "string",
      "minLength": 1
    },
    "openItems": {
      "description": "clarification + challenge ledger \u2014 see orchestrator \"Open-item ledger\". Each entry: { id, kind, raised_by, owner, blocking, status, \u2026 }; kind: clarification | challenge. status: open | resolved | withdrawn. A blocking+open entry HALTS the \u2605 Feature/Architecture Gate.",
      "$ref": "#/$defs/openItems"
    },
    "cost": {
      "description": "Token-cost accounting block (see the cost definition).",
      "$ref": "#/$defs/cost"
    },
    "github": {
      "description": "GitHub Projects sync envelope, filled by portfolio/_sync (null when authoring).",
      "$ref": "#/$defs/githubSync"
    },
    "parentEpic": {
      "description": "Parent Epic id this Feature realizes (null if unparented).",
      "type": [
        "string",
        "null"
      ]
    },
    "epicRationale": {
      "description": "Why this Feature belongs to its parent Epic.",
      "type": "string",
      "minLength": 1
    },
    "structurant": {
      "description": "Whether this Feature is structurant (architecturally significant; triggers an ADR and the Architecture Gate).",
      "type": "boolean"
    },
    "architectureInventory": {
      "description": "required when structurant=true; path to architecture/decision-inventory-F-N-*.md",
      "type": [
        "string",
        "null"
      ]
    },
    "adrs": {
      "description": "ADR ids this artifact depends on.",
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "pi": {
      "description": "Program Increment number this artifact is associated with.",
      "type": [
        "integer",
        "number",
        "string",
        "null"
