      "description": "Derivation provenance (narrowed subtype of the base contract's sources): refs to the upstream artifact(s) this feature-enabler was built from. Allowed source kinds: epic-enabler, architecture-runway.",
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "string",
        "pattern": "(^|/)([a-z0-9-]+\\.)?(epic-enabler|architecture-runway)\\.md$"
